mapper.select:
SELECT t.title AS title, CONCAT('截止 ', DATE_FORMAT(t.due_at, '%Y-%m-%d %H:%i'), '，负责人 ', COALESCE(ma.username, '—')) AS detail, a.id AS activityId FROM task t JOIN activity a ON a.id = t.activity_id LEFT JOIN organization_member m ON m.id = t.assignee_member_id LEFT JOIN account ma ON ma.id = m.account_id WHERE AND t.status IN ('PENDING', 'IN_PROGRESS') AND t.due_at IS NOT NULL AND t.due_at < #{now}
AND t.assignee_member_id = #{assigneeMemberId}
ORDER BY t.due_at ASC, t.id ASC LIMIT #{limit}

SELECT COUNT(*)
FROM registration r
JOIN activity a ON a.id = r.activity_id
WHERE a.org_id = #{orgId}
  AND r.account_id = #{accountId}
  AND r.status IN ('PENDING', 'APPROVED')
